      "path": "src/plugin.js",
      "content": "/**\n * DeepSeek Harness Intelligent UI — Host half.\n *\n * Registers the generative-UI tools (`ui_render`, `ui_patch`, `ui_render_widget`,\n * `ui_compose`), the `/ui` command and an optional system-prompt section. The\n * browser half (`./client`) renders each tool call in the `tool.call.toolview` slot.\n * @module deepseek-harness-intelligent-ui\n */\nimport { Config as ConfigSchema, resolveConfig } from './config.js';\nimport { composeEnabled } from './compose/compose.js';\nimport { COMPOSE_TOOL } from './compose/constants.js';\nimport { createUiSessionProjection } from './catalog/patch.js';\nimport { createComposeTool } from './tools/compose.js';\nimport { createRenderTool, RENDER_TOOL } from './tools/render.js';\nimport { createPatchTool, PATCH_TOOL } from './tools/patch.js';\nimport { createWidgetTool } from './tools/widget.js';\nimport { GUIDANCE_ORDER, guidanceText } from './guidance.js';\nimport { registerCommands } from './commands.js';\n\nexport const name = 'deepseek-harness-intelligent-ui';\nexport const inject = ['tools', 'commands'];\nexport const Config = ConfigSchema;\n\n/**\n * @param {import('@deepseek-ai/cordis').Context & Record<string, any>} ctx\n * @param {Record<string, unknown>} rawConfig\n */\nexport function apply(ctx, rawConfig) {\n  const config = resolveConfig(rawConfig);\n  // tools.register / commands.register are fiber effects: unloading this\n  // plugin unregisters everything, so no manual disposer bookkeeping.\n  if (config.enableCatalog) {\n    const unit = createUiSessionProjection({\n      render: RENDER_TOOL,\n      patch: PATCH_TOOL,\n      ...(config.enableCompose !== false ? { compose: COMPOSE_TOOL, config } : {}),\n    });\n    let activePromise;\n    ctx.inject(['sessionProjections'], (child) => {\n      const sp = child.sessionProjections;\n      if (!sp || typeof sp.register !== 'function') return;\n      let disposed = false;\n      const promise = Promise.resolve(sp.register(unit)).then(\n        (h) => (!disposed && h && typeof h.stateOf === 'function' ? h : undefined),\n        (err) => { child.logger?.warn?.(err); return undefined; },\n      );\n      activePromise = promise;\n      child.effect(() => () => {\n        disposed = true;\n        if (activePromise === promise) activePromise = undefined;\n      });\n    });\n    ctx.tools.register(createRenderTool(config));\n    ctx.tools.register(createPatchTool(config, () => activePromise));\n  }\n  if (config.enableWidget) ctx.tools.register(createWidgetTool(config));\n  // Composing needs something to compose; without a UI capability it is not offered.\n  if (composeEnabled(config)) ctx.tools.register(createComposeTool(config));\n  registerCommands(ctx.commands, config);\n\n  const text = config.injectGuidance ? guidanceText(config) : '';\n  if (text) {\n    // Optional: a composition without the system-prompt service still gets the tools.\n    ctx.inject(['systemPrompt'], (child) => {\n      child.systemPrompt.section({ name: 'intelligent-ui:guidance', order: GUIDANCE_ORDER, text });\n    });\n  }\n}\n"
    },
    {
      "path": "client-src/index.ts",
      "content": "/**\n * DeepSeek Harness Intelligent UI — browser half.\n *\n * Registers keyed `tool.call.toolview` entries for the generative-UI\n * tools and wires their interactions into the session as queued user\n * messages (through the same Session face the composer uses, so the message\n * echoes in the transcript immediately).\n */\nimport { PATCH_TOOL } from '../src/tools/patch.js'\nimport { RENDER_TOOL } from '../src/tools/render.js'\nimport { WIDGET_TOOL } from '../src/tools/widget.js'\nimport { COMPOSE_TOOL } from '../src/compose/constants.js'\nimport { PatchView } from './catalog/PatchView.tsx'\nimport { RenderView } from './catalog/RenderView.tsx'\nimport { ComposeView } from './compose/ComposeView.tsx'\nimport { en, NS, zh } from './locales.ts'\nimport { STYLES } from './styles.ts'\nimport { inlineView, TurnTail } from './TurnTail.tsx'\nimport { uiTurnDefinition } from './turn.ts'\nimport type { IntelligentUiInjected, SessionFace, SessionsFace, WorkspacesFace, UiWorkspaceFace } from './types/dsh.ts'\nimport { createNewSessionSender } from './new-session.ts'\nimport { WidgetView } from './widget/WidgetView.tsx'\n\nexport const inject = ['slots', 'locale', 'sessions', 'uiConversation']\n\ninterface ClientCtx {\n  /** Trusted companion plugin; absence leaves bindings/actions unavailable. */\n  get?: (name: string) => unknown\n  effect: (fn: () => (() => void) | void, label?: string) => void\n  locale: { register: (ns: string, dicts: Record<string, Record<string, string>>) => () => void }\n  slots: {\n    inject: (name: string, fn: () => unknown) => void\n    register: (entry: Record<string, unknown>, component: unknown) => unknown\n  }\n  sessions: SessionsFace\n  uiConversation: { events: { register: (definition: unknown) => unknown } }\n}\n\n/**\n * Send one text message into a session, echoing it like a composer submission.\n * @throws when the session is not open in this tab or the Host rejects it.\n */\nexport async function promptSession(sessions: ClientCtx['sessions'], sessionId: string, text: string): Promise<void> {\n  const session = sessions.binding(sessionId)?.session\n  if (!session) throw new Error('this conversation is not open')\n  const submission = session.beginSubmission?.({ mode: 'queue', text, attachments: [] })\n  let result: Awaited<ReturnType<SessionFace['prompt']>>\n  try {\n    result = await session.prompt([{ type: 'text', text }], 'queue', undefined, submission?.requestId)\n  } catch (err) {\n    submission?.abandon()\n    throw err\n  }\n  if (!result.ok) throw new Error(result.error?.message ?? 'the message was not accepted')\n}\n\nexport function apply(ctx: ClientCtx): void {\n  const sendNewSession = createNewSessionSender(ctx.sessions, () => ({\n    workspaces: ctx.get?.('workspaces') as WorkspacesFace | undefined,\n    uiWorkspace: ctx.get?.('uiWorkspace') as UiWorkspaceFace | undefined,\n  }))\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'intelligent-ui: dictionaries')\n\n  ctx.effect(() => {\n    const style = document.createElement('style')\n    style.dataset.owner = 'deepseek-harness-intelligent-ui'\n    style.textContent = STYLES\n    document.head.appendChild(style)\n    return () => style.remove()\n  }, 'intelligent-ui: styles')\n\n  const injected = (sessionId: string): IntelligentUiInjected => {\n    // Cordis direct property reads require a declared dependency. get() is its\n    // supported optional-service lookup and preserves legacy hosts without one.\n    const provider = ctx.get?.('intelligentUiControlled') as { forSession: (id: string) => IntelligentUiInjected['controlled'] } | undefined\n    return {\n      controlled: provider?.forSession(sessionId),\n      sendPrompt: text => promptSession(ctx.sessions, sessionId, text),\n      sendNewSessionPrompt: (text, uiId, nodeId) => sendNewSession(sessionId, text, uiId, nodeId),\n      sessionId,\n    }\n  }\n\n  // ui_compose is only registered by Hosts that have a UI capability; the slot\n  // key is harmless when the tool never appears in this session.\n  const views = [[RENDER_TOOL, RenderView], [PATCH_TOOL, PatchView], [WIDGET_TOOL, WidgetView], [COMPOSE_TOOL, ComposeView]] as const\n  for (const [key, view] of views) {\n    ctx.slots.inject('tool.call.toolview', () => ctx.slots.register(\n      { name: 'tool.call.toolview', key, locale: NS, inject: injected },\n      inlineView(view),\n    ))\n  }\n\n  // A finished Turn folds its tool calls away; re-present settled UIs beneath\n  // the reply (same pattern as ui-schedule's created-task card).\n  ctx.uiConversation.events.register(uiTurnDefinition)\n  ctx.slots.inject('conversation.chat.turnTail', () => ctx.slots.register(\n    { name: 'conversation.chat.turnTail', id: 'intelligent-ui', order: 15, locale: NS, inject: injected },\n    TurnTail,\n  ))\n}\n\nexport { createControlledRuntime } from '../src/controlled/runtime.js'\n\nexport { registerComponentExtension, CATALOG_API_VERSION } from './catalog/extensions.tsx'\nexport type { CatalogExtension, ComponentDefinition, ExtensionHandle, InferProps, ExtensionRenderContext, ExtensionRenderers } from './catalog/extensions.tsx'\n"
    },
    {
      "path": "src/tools/render.js",
      "content": "/**\n * `ui_render`: declarative generative UI. The model sends a flat component\n * list; the Web client renders it natively inside the tool card. execute()\n * only validates and acknowledges — interactions come back later as ordinary\n * user messages, so the agent never blocks on the UI.\n * @module deepseek-harness-intelligent-ui/tools/render\n */\nimport { catalogReference, componentTypes, validateTree } from '../catalog/catalog.js';\nimport { clientPolicy } from '../config.js';\n\nexport const RENDER_TOOL = 'ui_render';\n\n/**\n * JSON schema for a root-level `computed` array, shared by `ui_render` and by\n * `ui_compose`'s catalog blocks so both tools publish one contract. The Host\n * accepts exactly this shape (`src/catalog/catalog.js`); a capability the\n * parameters never mention is one models do not use.\n * @param {string} [description] - tool-specific wording.\n */\nexport function computedParam(description) {\n  return {\n    type: 'array',\n    description: description ?? 'Optional root-level formulas recomputed in the browser as the user edits: {id, expr, format?}. `id` is an identifier (must not repeat a Form field key); `expr` reads form values (field bindKey or name) and earlier computed ids; reference the result as {{id}} in text or {\"$computed\":\"id\"} in a numeric prop.',\n    items: {\n      type: 'object',\n      properties: {\n        id: { type: 'string', description: 'Identifier of the value, e.g. \"total\". Unique within this UI.' },\n        expr: { type: 'string', description: 'Arithmetic/boolean expression over form values and other computed ids, e.g. \"subtotal * 0.08\".' },\n        format: {\n          type: 'object',\n          description: 'Optional display format for {{id}} placeholders.',\n          properties: {\n            style: { type: 'string', enum: ['decimal', 'currency', 'percent'], description: 'Number style; percent multiplies by 100.' },\n            currency: { type: 'string', description: 'ISO 4217 code for the currency style, e.g. \"USD\".' },\n            minimumFractionDigits: { type: 'number', description: '0-20.' },\n            maximumFractionDigits: { type: 'number', description: '0-20.' },\n            locale: { type: 'string', description: 'BCP 47 locale, e.g. \"en-US\" (default).' },\n          },\n        },\n      },\n      required: ['id', 'expr'],\n    },\n  };\n}\n\n/**\n * @param {ReturnType<import('../config.js').resolveConfig>} config\n */\nexport function createRenderTool(config) {\n  return {\n    name: RENDER_TOOL,\n    get description() { return [\n      'Show the user an interactive UI (cards, tables, charts, KPI stats, tabs, timelines, function plots with live sliders, math formulas, Mermaid diagrams, buttons, forms) rendered natively in the chat.',\n      'Use it when structured or visual presentation answers better than prose: comparisons, data, dashboards, processes, formulas, functions to explore, choices, input collection.',\n      'Sorting, tabs, chart hover and Plot sliders work locally. Host-registered dataRef shares data and local queries between Table/Chart. Only prompt Buttons and Form submissions send model messages; action Buttons call the host allowlist.',\n      'Local linkage: a Form field `bindKey` (or the field name) becomes a shared variable; a root-level `computed` array of {id, expr, format?} derives values from those variables and other computed ids, recomputed in the browser on every edit with no round trip. Reference one as {{id}} inside a text prop or as {\"$computed\":\"id\"} in a numeric prop (Progress.value, Chart series values, Table filterValue).',\n      'Only reference dataRef scopes/ids and actionIds explicitly supplied by the host; never invent them. Unsupported hosts show an unavailable state. Send a FLAT list of components; containers reference children by id. The top-level `root` field is REQUIRED and holds the top component\\'s id (e.g. {\"root\":\"page\",\"components\":[{\"id\":\"page\",…}]}); naming a component \"root\" does not replace it.',\n      'Button clicks and Form submissions arrive later as the user\\'s next message — do not wait for them in this turn.',\n      `A dashboard or single-UI answer is mostly the UI: after calling, add at most one short sentence and do not repeat the UI content. If the user asked for a full analysis, lesson or report, write that prose in the reply${config.enableCompose !== false ? ' (or use ui_compose to interleave it)' : ''}; never cut the reasoning short to fit the card.`,\n      'Components:',\n      catalogReference(),\n    ].join('\\n'); },\n    get parameters() { return {\n      type: 'object',\n      properties: {\n        title: { type: 'string', description: 'Optional card title shown above the UI.' },\n        root: { type: 'string', description: 'REQUIRED: id of the top-level component. Always send it, before components.' },\n        components: {\n          type: 'array',\n          description: 'All components, parents before children is recommended (renders progressively while streaming).',\n          items: {\n            type: 'object',\n            properties: {\n              id: { type: 'string', description: 'Unique id.' },\n              type: { type: 'string', enum: componentTypes() },\n              componentVersion: { type: 'string', description: 'Required for extension types: exact version from the catalog. Omit for built-ins.' },\n              props: { type: 'object', description: 'Props for this component type (see the component list).' },\n              children: { type: 'array', items: { type: 'string' }, description: 'Child component ids (containers only).' },\n            },\n            required: ['id', 'type'],\n          },\n        },\n        computed: computedParam(),\n      },\n      required: ['root', 'components'],\n    }; },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          summary: { type: 'string' },\n          errors: { type: 'array', items: { type: 'string' } },\n          fixes: { type: 'array', items: { type: 'string' } },\n          normalized: { type: 'object' },\n        },\n        required: ['ok', 'summary'],\n      },\n      render: (_args, value) => [{\n        type: 'text',\n        text: value.ok\n          ? value.summary\n          : `${value.summary}\\n${(value.errors || []).map(e => `- ${e}`).join('\\n')}${value.fixes?.length ? `\\nSuggested fixes:\\n${value.fixes.map(f => `  * ${f}`).join('\\n')}` : ''}`,\n      }],\n      presentationMeta: (_args, value) => ({\n        ok: value.ok,\n        policy: clientPolicy(config),\n        ...(value.normalized ? { normalized: value.normalized } : {}),\n      }),\n    },\n    isConcurrencySafe: () => true,\n    async execute(rawArgs, exec) {\n      const args = rawArgs && typeof rawArgs === 'object' && !Array.isArray(rawArgs) ? structuredClone(rawArgs) : rawArgs;\n      const result = validateTree(args, { lenient: Boolean(config?.lenientValidation) });\n      if (!result.ok) {\n        return {\n          ok: false,\n          summary: `UI not rendered: ${result.errors.length} problem(s). Fix them and call ui_render again.`,\n          errors: result.errors.slice(0, 40),\n          ...(result.fixes?.length ? { fixes: result.fixes.slice(0, 20) } : {}),\n        };\n      }\n      const kinds = Object.entries(result.types).map(([t, n]) => (n > 1 ? `${n}x ${t}` : t)).join(', ');\n      const title = typeof args.title === 'string' && args.title ? ` \"${args.title}\"` : '';\n      const warn = result.warnings.length ? ` Warning: ${result.warnings.join('; ')}.` : '';\n      // The call id doubles as the UI's identity for later in-place patches.\n      const handle = exec?.callId ? ` uiId ${exec.callId}, version 1 (change it later with ui_patch).` : '';\n      return {\n        ok: true,\n        summary: `UI${title} is now displayed to the user (${result.count} components: ${kinds}).${warn}${handle} User interactions will arrive as new user messages.`,\n        ...(result.normalized ? {\n          normalized: JSON.parse(JSON.stringify({\n            ...(typeof args.title === 'string' ? { title: args.title } : {}),\n            root: args.root,\n            components: result.components ?? args.components,\n            ...(Array.isArray(args.computed) ? { computed: args.computed } : {}),\n          })),\n        } : {}),\n      };\n    },\n  };\n}\n"
    },
    {
      "path": "src/tools/patch.js",
      "content": "/**\n * `ui_patch`: update a UI shown earlier in this conversation in place, by\n * component id, instead of re-sending the whole tree. execute() rebuilds the\n * UI's current version from the session's own history (see catalog/patch.js),\n * applies the operations atomically and returns the complete next version in\n * `presentationMeta`, so the browser renders it without replaying anything and\n * a reload reproduces it from the durable `tool/result`.\n * @module deepseek-harness-intelligent-ui/tools/patch\n */\nimport { componentTypes } from '../catalog/catalog.js';\nimport { applyPatch, collectUis, outline, PATCH_LIMITS, PATCH_OPS } from '../catalog/patch.js';\nimport { clientPolicy } from '../config.js';\nimport { COMPOSE_TOOL } from '../compose/constants.js';\nimport { RENDER_TOOL } from './render.js';\n\nexport const PATCH_TOOL = 'ui_patch';\n\nconst nodeSchema = () => ({\n  type: 'object',\n  properties: {\n    id: { type: 'string', description: 'Unique new component id.' },\n    type: { type: 'string', enum: componentTypes() },\n    componentVersion: { type: 'string', description: 'Required exact extension version; omit for built-ins.' },\n    props: { type: 'object' },\n    children: { type: 'array', items: { type: 'string' } },\n  },\n  required: ['id', 'type'],\n});\n\n/**\n * The UIs of the calling conversation, or an explanation why there are none.\n * Combines the incremental `sessionProjections` state (which covers PTC\n * `tool/ptc-dispatch` sub-calls and pre-compaction turns) with\n * `session.deriveMessages()` fallback for older hosts and unit tests.\n * @param {any} exec - ToolRunContext.\n * @param {ReturnType<import('../config.js').resolveConfig>} config\n * @param {() => any} [getProjection]\n */\nasync function conversationUis(exec, config, getProjection) {\n  const session = exec?.agent?.session;\n  if (!session) return undefined;\n  let projected;\n  try {\n    const handle = typeof getProjection === 'function' ? await getProjection() : undefined;\n    if (handle && typeof handle.stateOf === 'function') {\n      const state = await handle.stateOf(session);\n      if (state && typeof state.uis === 'object' && state.uis !== null) {\n        projected = new Map(Object.entries(state.uis));\n      }\n    }\n  } catch { /* fallback to deriveMessages when session is a test double */ }\n  let derived;\n  if (typeof session.deriveMessages === 'function') {\n    try {\n      derived = collectUis(session.deriveMessages(), {\n        render: RENDER_TOOL,\n        patch: PATCH_TOOL,\n        ...(config.enableCompose !== false ? { compose: COMPOSE_TOOL, config } : {}),\n      });\n    } catch { /* preserve projected state if deriveMessages fails */ }\n  }\n  if (!projected && !derived) return undefined;\n  if (!projected) return derived;\n  if (!derived) return projected;\n  const merged = new Map(derived);\n  for (const [id, ui] of projected) {\n    const existing = merged.get(id);\n    if (!existing || (ui?.version ?? 0) >= (existing?.version ?? 0)) merged.set(id, ui);\n  }\n  return merged;\n}\n\n/**\n * @param {ReturnType<import('../config.js').resolveConfig>} config\n * @param {() => any} [getProjection]\n */\nexport function createPatchTool(config, getProjection) {\n  return {\n    name: PATCH_TOOL,\n    description: [\n      `Change a UI that ${RENDER_TOOL}, ${COMPOSE_TOOL} (a catalog block's uiId is \"<composition call id>#<block id>\") or an earlier ${PATCH_TOOL} already showed in THIS conversation, in place, without re-sending the whole UI.`,\n      'Address it by its uiId and the version you are changing (both are in the tool result that showed it); address components by their ids.',\n      'Components you do not touch keep their content and the user\\'s state (table sort, selected tab, form input, slider positions).',\n      'Operations, applied in order and all-or-nothing:',\n      '- setProps {id, props, unset?}: merge props into a component (e.g. {\"id\":\"chart\",\"props\":{\"kind\":\"line\"}}); unset lists prop names to remove.',\n      '- replaceNode {id, node:{type, props, children?}, nodes?}: replace one component\\'s type/props/children, keeping its id (its state resets).',\n      '- insertChild {parent, id, index?, nodes}: add the new component `id` (defined in `nodes`, with any descendants) under `parent`, at `index` (default: last).',\n      '- removeNode {id}: remove a component and everything under it (not the root). Keep Tabs labels in step with their children in the same patch.',\n      'A patch may drop a `Form` field or reuse a field key the answer already publishes, but it cannot introduce a NEW field key: the name could collide with a `computed` id that another block declares, which this block cannot see. Remove/reuse keys, or re-render the whole answer.',\n      `On ok=false nothing changed; fix the listed problems and retry. A stale baseVersion means the UI changed: patch the current version. Use ${RENDER_TOOL} instead for a new UI, a different root, or when most of the UI changes. Widgets (ui_render_widget) cannot be patched; render them again.`,\n    ].join('\\n'),\n    get parameters() { return {\n      type: 'object',\n      properties: {\n        uiId: { type: 'string', description: 'uiId of the UI to change, from the tool result that showed it.' },\n        baseVersion: { type: 'integer', description: 'The UI version this patch is based on (1 after ui_render; each patch result reports the new version).' },\n        title: { type: 'string', description: 'Optional new card title.' },\n        ops: {\n          type: 'array',\n          description: `1-${PATCH_LIMITS.ops} operations, applied in order.`,\n          items: {\n            type: 'object',\n            properties: {\n              op: { type: 'string', enum: [...PATCH_OPS] },\n              id: { type: 'string', description: 'Target component id (insertChild: the new child id).' },\n              props: { type: 'object', description: 'setProps: props to merge.' },\n              unset: { type: 'array', items: { type: 'string' }, description: 'setProps: prop names to remove.' },\n              node: {\n                type: 'object',\n                description: 'replaceNode: the replacement (same id).',\n                properties: {\n                  type: { type: 'string', enum: componentTypes() },\n                  componentVersion: { type: 'string', description: 'Required exact extension version; omit for built-ins.' },\n                  props: { type: 'object' },\n                  children: { type: 'array', items: { type: 'string' } },\n                },\n                required: ['type'],\n              },\n              parent: { type: 'string', description: 'insertChild: the container to insert into.' },\n              index: { type: 'integer', description: 'insertChild: position among the parent\\'s children.' },\n              nodes: { type: 'array', items: nodeSchema(), description: 'insertChild/replaceNode: new components (flat list, children by id).' },\n            },\n            required: ['op'],\n          },\n        },\n      },\n      required: ['uiId', 'baseVersion', 'ops'],\n    }; },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          ok: { type: 'boolean' },\n          summary: { type: 'string' },\n          errors: { type: 'array', items: { type: 'string' } },\n          code: { type: 'string' },\n          ui: { type: 'object' },\n        },\n        required: ['ok', 'summary'],\n      },\n      render: (_args, value) => [{ type: 'text', text: value.ok ? value.summary : `${value.summary}\\n${(value.errors || []).map(e => `- ${e}`).join('\\n')}` }],\n      // The complete next version travels to the browser; the model only sees the summary.\n      presentationMeta: (_args, value) => (value.ok ? { ok: true, policy: clientPolicy(config), ui: value.ui } : { ok: false, policy: clientPolicy(config), ...(value.code ? { code: value.code } : {}) }),\n    },\n    // Exclusive: patches of one UI must apply in a single, replayable order.\n    isConcurrencySafe: () => false,\n    async execute(args, exec) {\n      const refuse = (errors, code = 'invalid') => ({\n        ok: false,\n        code,\n        summary: `UI not changed: ${errors.length} problem(s). The user still sees the previous version.`,\n        errors,\n      });\n      if (typeof args !== 'object' || args === null || typeof args.uiId !== 'string' || args.uiId === '') {\n        return refuse(['uiId: expected the uiId of a UI shown earlier in this conversation']);\n      }\n      const uis = await conversationUis(exec, config, getProjection);\n      if (!uis) return refuse([`${PATCH_TOOL} is only available inside a conversation; call ${RENDER_TOOL} with the complete UI`], 'unavailable');\n      const ui = uis.get(args.uiId);\n      if (!ui) {\n        const known = [...uis.values()].slice(-5).map(u => `${u.uiId} (v${u.version}${u.title ? ` \"${u.title}\"` : ''})`);\n        return refuse([`uiId: no UI ${JSON.stringify(args.uiId)} in this conversation${known.length ? `; known: ${known.join(', ')}` : ''}. If it is no longer available, call ${RENDER_TOOL} with the complete UI.`], 'unknown');\n      }\n      const result = applyPatch(ui, args);\n      if (!result.ok) return refuse(result.errors, result.code);\n      const next = result.ui;\n      const title = next.title ? ` \"${next.title}\"` : '';\n      const warn = result.warnings.length ? ` Warning: ${result.warnings.join('; ')}.` : '';\n      return {\n        ok: true,\n        summary: `UI${title} updated in place: uiId ${next.uiId}, now version ${next.version} (changed: ${result.changed.join(', ') || 'title'}).${warn} Components: ${outline(next)}.`,\n        ui: next,\n      };\n    },\n  };\n}\n"
    },
    {
      "path": "src/catalog/patch.js",
      "content": "/**\n * Incremental updates of an existing `ui_render` UI (`ui_patch`).\n *\n * A UI is identified by `uiId` (the call id of the `ui_render` that created\n * it) and versioned: the render is version 1 and every accepted patch adds\n * one. Components keep their ids across versions, so the browser keeps the\n * interaction state (sort, tab, form values, slider positions) of every\n * component a patch did not replace.\n *\n * Nothing is stored on the Host: {@link collectUis} replays this session's own\n * history (the messages the model sees), which makes the outcome deterministic\n * across restarts and confines patches to UIs of the same conversation.\n * @module deepseek-harness-intelligent-ui/catalog/patch\n */\nimport { composeUiId, compositionFieldKeys, validateComposition } from '../compose/compose.js';\nimport { CATALOG, LIMITS, validateTree } from './catalog.js';\n\nexport const PATCH_OPS = Object.freeze(['setProps', 'replaceNode', 'insertChild', 'removeNode']);\n\n/** Upper bounds for one patch call. */\nexport const PATCH_LIMITS = Object.freeze({ ops: 50, nodesPerOp: LIMITS.components });\n\n/** Allowed fields per op (besides `op`). */\nconst OP_FIELDS = Object.freeze({\n  setProps: ['id', 'props', 'unset'],\n  replaceNode: ['id', 'node', 'nodes'],\n  insertChild: ['parent', 'id', 'index', 'nodes'],\n  removeNode: ['id'],\n});\n\n/**\n * @typedef {{ id: string, type: string, props?: Record<string, unknown>, children?: string[] }} UiNode\n * @typedef {{ uiId: string, version: number, title?: string, root: string, components: UiNode[], computed?: unknown[], scope?: string[], computedIds?: string[], staleFields?: string[] }} UiSnapshot\n */\n\nfunction isPlainObject(v) {\n  return typeof v === 'object' && v !== null && !Array.isArray(v);\n}\n\nconst clone = v => JSON.parse(JSON.stringify(v));\n\n/** Legacy built-ins alone accept props.children; extensions use their exact schema. */\nfunction normalize(node) {\n  if (Object.hasOwn(CATALOG, node.type) && isPlainObject(node.props) && Object.hasOwn(node.props, 'children')) {\n    if (node.children === undefined && Array.isArray(node.props.children)) node.children = node.props.children;\n    delete node.props.children;\n  }\n  return node;\n}\n\n/**\n * Normalize a validated `ui_render` payload into a snapshot.\n * @param {string} uiId\n * @param {any} args - `ui_render` arguments that passed {@link validateTree}.\n * @param {{ scope?: readonly string[], computedIds?: readonly string[] }} [extra] -\n *   answer-wide context of a composition block: the field keys its siblings\n *   publish and the computed ids they declare (a block patch may collide with\n *   neither, and the block itself cannot see them).\n * @returns {UiSnapshot}\n */\nexport function snapshotOf(uiId, args, extra = {}) {\n  const tree = clone(args);\n  const byId = new Map(tree.components.map(n => [n.id, normalize(n)]));\n  const scope = Array.isArray(extra.scope) ? [...extra.scope] : undefined;\n  const computedIds = Array.isArray(extra.computedIds) ? [...extra.computedIds] : undefined;\n  return {\n    uiId,\n    version: 1,\n    ...(typeof tree.title === 'string' && tree.title ? { title: tree.title } : {}),\n    root: tree.root,\n    components: reachable(tree.root, byId),\n    // Formulas travel with the version: a patch must not drop them.\n    ...(Array.isArray(tree.computed) ? { computed: tree.computed } : {}),\n    ...(scope && scope.length ? { scope } : {}),\n    ...(computedIds && computedIds.length ? { computedIds } : {}),\n  };\n}\n\n/** Components reachable from `root`, parents before children (renders progressively). */\nfunction reachable(root, byId) {\n  const out = [];\n  const seen = new Set();\n  const walk = (id) => {\n    const node = byId.get(id);\n    if (!node || seen.has(id)) return;\n    seen.add(id);\n    out.push(node);\n    for (const c of node.children ?? []) walk(c);\n  };\n  walk(root);\n  return out;\n}\n\n/**\n * Field keys published by the `Form` nodes of one tree: a field's `bindKey`\n * (with its `name` as an alias) and a single-field form's `bindKey`. The same\n * rule `compositionFieldKeys` and the renderer use, so a patch can tell which\n * shared values this block itself produced.\n * @param {readonly UiNode[]} components\n * @returns {Set<string>}\n */\nfunction publishedFieldKeys(components) {\n  const keys = new Set();\n  for (const node of components ?? []) {\n    if (!isPlainObject(node) || !isPlainObject(node.props)) continue;\n    if (node.type === 'Segmented') {\n      if (typeof node.props.bindKey === 'string' && node.props.bindKey) keys.add(node.props.bindKey);\n      continue;\n    }\n    if (node.type !== 'Form') continue;\n    const fields = Array.isArray(node.props.fields) ? node.props.fields.filter(isPlainObject) : [];\n    for (const field of fields) {\n      if (typeof field.bindKey === 'string' && field.bindKey) keys.add(field.bindKey);\n      if (typeof field.name === 'string' && field.name) keys.add(field.name);\n    }\n    if (fields.length === 1 && typeof node.props.bindKey === 'string' && node.props.bindKey) keys.add(node.props.bindKey);\n  }\n  return keys;\n}\n\n/**\n * Check a new component definition (shape only; props are checked on the whole tree).\n * @returns {string | undefined} a problem, or undefined.\n */\nfunction checkNewNode(node, at) {\n  if (!isPlainObject(node)) return `${at}: expected a component object`;\n  if (typeof node.id !== 'string' || node.id === '') return `${at}.id: expected non-empty string`;\n  if (typeof node.type !== 'string') return `${at}(${node.id}).type: expected string`;\n  if (node.children !== undefined && (!Array.isArray(node.children) || node.children.some(c => typeof c !== 'string'))) {\n    return `${at}(${node.id}).children: expected array of component ids`;\n  }\n  const extra = Object.keys(node).find(k => !['id', 'type', 'componentVersion', 'props', 'children'].includes(k));\n  return extra ? `${at}(${node.id}).${extra}: unknown field` : undefined;\n}\n\n/**\n * Apply one `ui_patch` call to the current snapshot. All-or-nothing: on any\n * problem the snapshot is left untouched and the errors say what to fix.\n * @param {UiSnapshot} ui - current version.\n * @param {any} args - `ui_patch` arguments.\n * @returns {{ ok: true, ui: UiSnapshot, changed: string[], warnings: string[] } | { ok: false, errors: string[], code: 'invalid' | 'stale' }}\n */\nexport function applyPatch(ui, args) {\n  const fail = (errors, code = 'invalid') => ({ ok: false, errors, code });\n  if (!isPlainObject(args)) return fail(['arguments: expected object']);\n  for (const key of Object.keys(args)) {\n    if (!['uiId', 'baseVersion', 'title', 'ops'].includes(key)) return fail([`${key}: unknown field`]);\n  }\n  if (!Number.isInteger(args.baseVersion)) return fail([`baseVersion: expected the integer version you are patching (current: ${ui.version})`]);\n  if (args.baseVersion !== ui.version) {\n    return fail([`baseVersion: UI ${JSON.stringify(ui.uiId)} is at version ${ui.version}, not ${args.baseVersion}; it changed since you read it. Re-derive the patch from version ${ui.version} and call ui_patch again with baseVersion ${ui.version}.`], 'stale');\n  }\n  if (args.title !== undefined && typeof args.title !== 'string') return fail(['title: expected string']);\n  if (!Array.isArray(args.ops) || args.ops.length === 0) return fail(['ops: expected a non-empty array']);\n  if (args.ops.length > PATCH_LIMITS.ops) return fail([`ops: more than ${PATCH_LIMITS.ops} operations; call ui_render with the complete UI instead`]);\n\n  const nodes = new Map(clone(ui.components).map(n => [n.id, n]));\n  const parentOf = new Map();\n  for (const n of nodes.values()) for (const c of n.children ?? []) parentOf.set(c, n.id);\n  const changed = new Set();\n  const added = new Set();\n\n  const addNodes = (list, at) => {\n    if (list === undefined) return undefined;\n    if (!Array.isArray(list)) return `${at}: expected array of new components`;\n    if (list.length > PATCH_LIMITS.nodesPerOp) return `${at}: more than ${PATCH_LIMITS.nodesPerOp} components`;\n    for (let j = 0; j < list.length; j++) {\n      const problem = checkNewNode(list[j], `${at}[${j}]`);\n      if (problem) return problem;\n      if (nodes.has(list[j].id)) return `${at}[${j}].id: ${JSON.stringify(list[j].id)} already exists; give new components new ids, or use setProps/replaceNode on the existing one`;\n      const node = normalize(clone(list[j]));\n      nodes.set(node.id, node);\n      added.add(node.id);\n      changed.add(node.id);\n    }\n    // New components may reference each other; their parents are wired by the tree check below.\n    for (const id of list.map(n => n.id)) for (const c of nodes.get(id).children ?? []) parentOf.set(c, id);\n    return undefined;\n  };\n  const existing = (id, at) => {\n    if (typeof id !== 'string' || id === '') return `${at}: expected a component id`;\n    if (!nodes.has(id)) return `${at}: unknown component id ${JSON.stringify(id)} in UI ${JSON.stringify(ui.uiId)} version ${ui.version}`;\n    return undefined;\n  };\n\n  for (let i = 0; i < args.ops.length; i++) {\n    const op = args.ops[i];\n    const at = `ops[${i}]`;\n    if (!isPlainObject(op)) return fail([`${at}: expected object`]);\n    if (!PATCH_OPS.includes(op.op)) return fail([`${at}.op: expected one of ${PATCH_OPS.join(' | ')}, got ${JSON.stringify(op.op)}`]);\n    const extra = Object.keys(op).find(k => k !== 'op' && !OP_FIELDS[op.op].includes(k));\n    if (extra) return fail([`${at}.${extra}: not a field of ${op.op} (allowed: ${OP_FIELDS[op.op].join(', ')})`]);\n    let problem;\n    switch (op.op) {\n      case 'setProps': {\n        problem = existing(op.id, `${at}.id`);\n        if (problem) break;\n        if (op.props === undefined && op.unset === undefined) { problem = `${at}: give props and/or unset`; break; }\n        if (op.props !== undefined && !isPlainObject(op.props)) { problem = `${at}.props: expected object`; break; }\n        if (op.props && Object.hasOwn(op.props, 'children')) { problem = `${at}.props.children: children are not props; use insertChild/removeNode/replaceNode`; break; }\n        if (op.unset !== undefined && (!Array.isArray(op.unset) || op.unset.some(k => typeof k !== 'string'))) { problem = `${at}.unset: expected array of prop names`; break; }\n        const node = nodes.get(op.id);\n        const props = { ...(node.props ?? {}), ...clone(op.props ?? {}) };\n        for (const k of op.unset ?? []) delete props[k];\n        node.props = props;\n        changed.add(op.id);\n        break;\n      }\n      case 'replaceNode': {\n        problem = existing(op.id, `${at}.id`);\n        if (problem) break;\n        if (!isPlainObject(op.node)) { problem = `${at}.node: expected { type, props, children }`; break; }\n        if (op.node.id !== undefined && op.node.id !== op.id) { problem = `${at}.node.id: must equal ${JSON.stringify(op.id)} (a replaced component keeps its id; remove it and insert a new one to change ids)`; break; }\n        problem = checkNewNode({ ...op.node, id: op.id }, `${at}.node`) ?? addNodes(op.nodes, `${at}.nodes`);\n        if (problem) break;\n        const prev = nodes.get(op.id);\n        for (const c of prev.children ?? []) if (parentOf.get(c) === op.id) parentOf.delete(c);\n        const next = normalize({ id: op.id, type: op.node.type, ...(op.node.componentVersion !== undefined ? { componentVersion: op.node.componentVersion } : {}), ...(op.node.props !== undefined ? { props: clone(op.node.props) } : {}), ...(op.node.children !== undefined ? { children: [...op.node.children] } : {}) });\n        nodes.set(op.id, next);\n        for (const c of next.children ?? []) parentOf.set(c, op.id);\n        changed.add(op.id);\n        break;\n      }\n      case 'insertChild': {\n        problem = existing(op.parent, `${at}.parent`) ?? addNodes(op.nodes, `${at}.nodes`) ?? existing(op.id, `${at}.id`);\n        if (problem) break;\n        if (op.id === ui.root) { problem = `${at}.id: the root cannot be inserted as a child`; break; }\n        if (parentOf.has(op.id)) {\n          problem = `${at}.id: ${JSON.stringify(op.id)} already has a parent (${parentOf.get(op.id)}); removeNode it first or insert a new component`;\n          break;\n        }\n        const parent = nodes.get(op.parent);\n        const kids = [...(parent.children ?? [])];\n        const index = op.index === undefined ? kids.length : op.index;\n        if (!Number.isInteger(index) || index < 0 || index > kids.length) { problem = `${at}.index: expected an integer from 0 to ${kids.length}`; break; }\n        kids.splice(index, 0, op.id);\n        parent.children = kids;\n        parentOf.set(op.id, op.parent);\n        changed.add(op.parent);\n        changed.add(op.id);\n        break;\n      }\n      case 'removeNode': {\n        problem = existing(op.id, `${at}.id`);\n        if (problem) break;\n        if (op.id === ui.root) { problem = `${at}.id: the root cannot be removed; replaceNode it or call ui_render with a new UI`; break; }\n        const parentId = parentOf.get(op.id);\n        const parent = parentId === undefined ? undefined : nodes.get(parentId);\n        if (parent) {\n          parent.children = (parent.children ?? []).filter(c => c !== op.id);\n          changed.add(parentId);\n        }\n        parentOf.delete(op.id);\n        nodes.delete(op.id);\n        changed.delete(op.id);\n        break;\n      }\n    }\n    if (problem) return fail([problem]);\n  }\n\n  const title = args.title !== undefined ? args.title : ui.title;\n  const components = reachable(ui.root, nodes);\n  const computed = Array.isArray(ui.computed) ? ui.computed : undefined;\n  // A composition block's formulas may also read fields a sibling block\n  // publishes; `scope` carries those names (see collectUis).\n  const scope = Array.isArray(ui.scope) ? ui.scope : undefined;\n  const computedIds = Array.isArray(ui.computedIds) ? ui.computedIds : undefined;\n  const before = publishedFieldKeys(ui.components);\n  const after = publishedFieldKeys(components);\n  // A patch may only (re)publish field keys the answer already knows: its own\n  // previous keys or one `scope` declares. A brand-new name would join the\n  // answer-wide pool without the Host being able to rule out a collision with\n  // another block's `computed` id (this block cannot see its siblings) — the\n  // resulting one-name-two-values state is exactly what ui_compose rejects.\n  const introduced = [...after].filter(key => !before.has(key));\n  // This block's own ids are checked against its own fields by validateTree\n  // below (with the precise path); only a sibling's id is invisible here.\n  const ownIds = new Set(Array.isArray(computed) ? computed.filter(isPlainObject).map(c => c.id).filter(id => typeof id === 'string') : []);\n  const reserved = new Set((computedIds ?? []).filter(id => !ownIds.has(id)));\n  for (const key of introduced) {\n    if (reserved.has(key)) {\n      return fail([`ops: the patched components publish field key ${JSON.stringify(key)}, but another block of this answer declares the computed id ${JSON.stringify(key)}; one name cannot be both a field and a formula. Pick a different field name.`]);\n    }\n    if (scope && !scope.includes(key)) {\n      return fail([`ops: the patched components publish the new field key ${JSON.stringify(key)}; a block patch may only re-publish the field keys this answer already shares (${scope.length ? scope.join(', ') : 'none'}), because a new name can collide with a sibling block's computed id. Remove the field, reuse an existing key, or call ui_compose again with the complete answer.`]);\n    }\n  }\n  // A block that removes (or renames) the form it published a shared value\n  // through leaves a value no input of its own backs any more. `scope` stays\n  // (a sibling block may publish the same key), but the browser is told which\n  // keys this version no longer produces and must not resurrect their last\n  // value as if the removed input were still there.\n  const staleFields = scope ? scope.filter(key => before.has(key) && !after.has(key)) : [];\n  const previous = Array.isArray(ui.staleFields) ? ui.staleFields.filter(key => scope?.includes(key) && !after.has(key)) : [];\n  const retired = [...new Set([...previous, ...staleFields])];\n  // The whole next version passes the same checks as a fresh ui_render.\n  const check = validateTree(\n    clone({ ...(title ? { title } : {}), root: ui.root, components, ...(computed ? { computed } : {}) }),\n    scope ? { fields: scope } : undefined,\n  );\n  if (!check.ok) return fail(check.errors.slice(0, 40));\n  const reached = new Set(components.map(n => n.id));\n  const dropped = [...added].filter(id => !reached.has(id));\n  const warnings = dropped.length ? [`new components not attached anywhere (dropped): ${dropped.join(', ')}`] : [];\n  return {\n    ok: true,\n    ui: {\n      uiId: ui.uiId, version: ui.version + 1, ...(title ? { title } : {}), root: ui.root, components,\n      ...(computed ? { computed } : {}), ...(scope ? { scope } : {}),\n      ...(computedIds ? { computedIds } : {}),\n      ...(retired.length ? { staleFields: retired } : {}),\n    },\n    changed: [...changed].filter(id => reached.has(id)),\n    warnings,\n  };\n}\n\nconst MAX_CALL_ARGUMENT_CHARS = 512_000;\n\n/**\n * Parse raw tool call arguments (JSON string or pre-parsed plain object) within\n * a defensive size bound.\n * @param {unknown} raw\n * @returns {Record<string, any> | undefined}\n */\nfunction parseCallArguments(raw) {\n  if (typeof raw === 'string') {\n    if (raw.length > MAX_CALL_ARGUMENT_CHARS) return undefined;\n    try {\n      const parsed = JSON.parse(raw);\n      return isPlainObject(parsed) ? parsed : undefined;\n    } catch { return undefined; }\n  }\n  if (isPlainObject(raw)) {\n    try {\n      const serialized = JSON.stringify(raw);\n      return serialized.length <= MAX_CALL_ARGUMENT_CHARS ? JSON.parse(serialized) : undefined;\n    } catch { return undefined; }\n  }\n  return undefined;\n}\n\n/**\n * Convert a Map or plain object into a null-prototype dictionary so keys like\n * `__proto__` or `constructor` remain inert own properties.\n * @param {Iterable<[string, any]>} entries\n * @returns {Record<string, any>}\n */\nfunction toSafeRecord(entries) {\n  const out = Object.create(null);\n  for (const [k, v] of entries) {\n    if (typeof k === 'string' && k !== '') out[k] = v;\n  }\n  return out;\n}\n\n/**\n * Apply one settled UI tool call (`ui_render`, `ui_compose`, `ui_patch`) to a\n * mutable Map of UI snapshots. Returns true when `uis` changed.\n * @param {Map<string, UiSnapshot>} uis\n * @param {string} callId\n * @param {string} name\n * @param {unknown} rawArgs\n * @param {{ content?: readonly any[], meta?: unknown }} outcome\n * @param {{ render: string, patch: string, compose?: string, config?: any }} tools\n */\nfunction applySettledUiCall(uis, callId, name, rawArgs, outcome, tools) {\n  const args = parseCallArguments(rawArgs);\n  if (!args) return false;\n  if (tools.compose !== undefined && name === tools.compose) {\n    // deriveMessages omits presentationMeta, so accept either presentationMeta.ok === true\n    // (session events / PTC dispatches) or the tool's positive text acknowledgment.\n    const metaOk = isPlainObject(outcome.meta) && outcome.meta.ok === true;\n    const textOk = Array.isArray(outcome.content) && outcome.content.some(b => b?.type === 'text' && b.text?.startsWith('Composed answer'));\n    if (!metaOk && !textOk) return false;\n    const config = tools.config ?? {};\n    const composed = validateComposition(clone(args ?? null), config, {\n      requireCatalog: config.enableCatalog !== false,\n      requireWidget: config.enableWidget !== false,\n    });\n    if (!composed.ok) return false;\n    const scope = [...compositionFieldKeys(composed.blocks)];\n    // Every computed id of the answer, so a block patch can recognise a\n    // field key that a *sibling* block already uses for a formula.\n    const computedIds = [];\n    for (const block of composed.blocks) {\n      if (block.type !== 'catalog' || !Array.isArray(block.computed)) continue;\n      for (const formula of block.computed) {\n        if (isPlainObject(formula) && typeof formula.id === 'string') computedIds.push(formula.id);\n      }\n    }\n    let changed = false;\n    for (const block of composed.blocks) {\n      if (block.type !== 'catalog') continue;\n      const uiId = composeUiId(callId, block.id);\n      uis.set(uiId, snapshotOf(uiId, {\n        title: block.title, root: block.root, components: block.components,\n        ...(Array.isArray(block.computed) ? { computed: block.computed } : {}),\n      }, { scope, computedIds }));\n      changed = true;\n    }\n    return changed;\n  }\n  if (name === tools.render) {\n    const cloned = clone(args ?? null);\n    if (!validateTree(cloned, { lenient: Boolean(tools.config?.lenientValidation) }).ok) return false;\n    uis.set(callId, snapshotOf(callId, cloned));\n    return true;\n  }\n  if (name === tools.patch) {\n    const ui = isPlainObject(args) && typeof args.uiId === 'string' ? uis.get(args.uiId) : undefined;\n    if (!ui) return false;\n    const result = applyPatch(ui, args);\n    if (!result.ok) return false;\n    uis.set(ui.uiId, result.ui);\n    return true;\n  }\n  return false;\n}\n\n/**\n * Rebuild the current version of every UI in one conversation from its message\n * history: each `ui_render` call that settled without error and validates, then\n * each settled `ui_patch` call in result order. Patches are deterministic, so\n * replaying them reproduces exactly the versions the user saw. Calls without a\n * result yet (including the one being executed) are ignored.\n * Catalog blocks of `ui_compose` calls (`tools.compose`) join the same map under\n * their derived `<callId>#<blockId>` identity, so one patch protocol addresses both.\n * @param {readonly any[]} messages - `Session.deriveMessages()`.\n * @param {{ render: string, patch: string, compose?: string, config?: any }} tools - tool names.\n * @returns {Map<string, UiSnapshot>}\n */\nexport function collectUis(messages, tools) {\n  const calls = new Map();\n  const uis = new Map();\n  const relevant = name => name === tools.render || name === tools.patch || (tools.compose !== undefined && name === tools.compose);\n  for (const m of messages) {\n    if (m?.role === 'assistant' && Array.isArray(m.content)) {\n      for (const b of m.content) {\n        if (b?.type === 'tool-call' && relevant(b.name)) calls.set(b.id, b);\n      }\n      continue;\n    }\n    if (m?.role !== 'tool' || m.isError === true) continue;\n    const call = calls.get(m.toolCallId);\n    if (!call) continue;\n    calls.delete(m.toolCallId);\n    applySettledUiCall(uis, call.id, call.name, call.arguments, { content: m.content }, tools);\n  }\n  return uis;\n}\n\n/**\n * Pure incremental fold over one committed DSH SessionEvent (`tool/call`,\n * `tool/result`, or `tool/ptc-dispatch` from the PTC executor). Returns the\n * exact same `state` reference when an event does not change pending calls or\n * settled UI snapshots.\n * @param {{ pending: Record<string, { name: string, arguments: unknown }>, uis: Record<string, UiSnapshot> }} state\n * @param {any} event\n * @param {{ render: string, patch: string, compose?: string, config?: any }} tools\n */\nexport function foldUiEvent(state, event, tools) {\n  if (!isPlainObject(event) || !isPlainObject(event.data)) return state;\n  const relevant = name => name === tools.render || name === tools.patch || (tools.compose !== undefined && name === tools.compose);\n  const data = event.data;\n  if (event.type === 'tool/call') {\n    if (!relevant(data.name) || typeof data.callId !== 'string' || data.callId === '') return state;\n    const nextPending = toSafeRecord(Object.entries(state.pending));\n    nextPending[data.callId] = { name: data.name, arguments: data.arguments };\n    return {\n      pending: nextPending,\n      uis: state.uis,\n    };\n  }\n  if (event.type === 'tool/result') {\n    if (event.surfaceOp !== undefined && event.surfaceOp !== 'append') return state;\n    const message = isPlainObject(data.message) ? data.message : {};\n    const callId = isPlainObject(message.source) && typeof message.source.callId === 'string'\n      ? message.source.callId\n      : (typeof data.callId === 'string' ? data.callId : '');\n    if (!callId || !Object.hasOwn(state.pending, callId)) return state;\n    const call = state.pending[callId];\n    const nextPending = toSafeRecord(Object.entries(state.pending));\n    delete nextPending[callId];\n    const failed = message.isError === true || data.isError === true || isPlainObject(data.error)\n      || (isPlainObject(data.meta) && data.meta.ok === false);\n    if (failed) return { pending: nextPending, uis: state.uis };\n    const map = new Map(Object.entries(state.uis));\n    const changed = applySettledUiCall(map, callId, call.name, call.arguments, { content: message.content, meta: data.meta }, tools);\n    return {\n      pending: nextPending,\n      uis: changed ? toSafeRecord(map) : state.uis,\n    };\n  }\n  if (event.type === 'tool/ptc-dispatch') {\n    if (event.surfaceOp !== undefined && event.surfaceOp !== 'append') return state;\n    if (!relevant(data.name) || typeof data.subCallId !== 'string' || data.subCallId === '') return state;\n    const failed = data.isError === true || isPlainObject(data.error)\n      || (isPlainObject(data.meta) && data.meta.ok === false);\n    if (failed) return state;\n    const map = new Map(Object.entries(state.uis));\n    const changed = applySettledUiCall(map, data.subCallId, data.name, data.arguments, { content: data.content, meta: data.meta }, tools);\n    return changed ? { pending: state.pending, uis: toSafeRecord(map) } : state;\n  }\n  return state;\n}\n\n/**\n * Rebuild every UI snapshot from a sequence of DSH SessionEvents (including\n * PTC `tool/ptc-dispatch` sub-calls and pre-compaction turns).\n * @param {readonly any[]} events\n * @param {{ render: string, patch: string, compose?: string, config?: any }} tools\n * @returns {Map<string, UiSnapshot>}\n */\nexport function collectUisFromEvents(events, tools) {\n  let state = { pending: Object.create(null), uis: Object.create(null) };\n  for (const row of events ?? []) {\n    const event = isPlainObject(row?.event) ? row.event : row;\n    state = foldUiEvent(state, event, tools);\n  }\n  return new Map(Object.entries(state.uis));\n}\n\n/**\n * Host-only `SessionProjectionRegistry` unit definition (`ctx.sessionProjections`).\n * Folds committed `tool/call`, `tool/result` and `tool/ptc-dispatch` events\n * without calling deprecated synchronous Session event readers.\n * @param {{ render: string, patch: string, compose?: string, config?: any }} tools\n */\nexport function createUiSessionProjection(tools) {\n  const isRecord = (v) => Boolean(v) && typeof v === 'object' && !Array.isArray(v);\n  return {\n    key: 'intelligent-ui.catalog-uis',\n    stateVersion: 1,\n    stateSchema: {\n      parse(value) {\n        if (!isRecord(value) || !isRecord(value.pending) || !isRecord(value.uis)) {\n          throw new Error('invalid intelligent-ui session projection state');\n        }\n        return value;\n      },\n    },\n    init: () => ({ pending: Object.create(null), uis: Object.create(null) }),\n    apply: (state, event) => foldUiEvent(state, event, tools),\n  };\n}\n\n/** Compact `id:Type` outline the model can address in its next patch. */\nexport function outline(ui, max = 80) {\n  const parts = ui.components.slice(0, max).map(n => `${n.id}:${n.type}`);\n  if (ui.components.length > max) parts.push(`… ${ui.components.length - max} more`);\n  return parts.join(', ');\n}\n"
    },
    {
      "path": "client-src/widget/WidgetFrame.tsx",
      "content": "import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'\nimport { contextOf, type ControlledEnv, type ActionRequest } from '../controlled.ts'\nimport { BridgeError, BridgeGuard, readFrameMessage } from '../bridge.ts'\nimport type { WidgetPolicy } from '../policy.ts'\nimport { getUiState, setUiState } from '../state.ts'\nimport { onThemeChange, readTheme } from '../theme.ts'\nimport { buildFrameDocument, codePayload, schemeOf, themeCss } from './frame.ts'\nimport { processPartialHtml } from './partial-html.ts'\n\n/** Last known height per call, so a re-mounted frame opens at its previous size. */\nconst heights = new Map<string, number>()\n\nfunction token(): string {\n  const bytes = new Uint8Array(16)\n  crypto.getRandomValues(bytes)\n  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')\n}\n\nexport interface WidgetFrameProps extends ControlledEnv {\n  /** State/height key; one per rendered surface. */\n  callId: string\n  mode: 'preview' | 'final'\n  css: string\n  html: string\n  jsFunctions?: string\n  jsExpressions?: readonly string[]\n  resourceLibraries?: readonly string[]\n  initialHeight?: number\n  policy: WidgetPolicy\n  title: string\n  /** Shown instead of the frame after the widget navigates out of its sandbox. */\n  strayedMessage?: string\n  sendPrompt: (text: string) => Promise<void>\n  /** Persist control values / UI.state / height for this callId (default true). */\n  persist?: boolean\n  /** Bump to rebuild the frame from scratch (manual reload after script errors). */\n  generation?: number\n  onSending?: (sending: boolean) => void\n  onSent?: (ok: boolean, reason?: string) => void\n  onErrors?: (errors: readonly string[]) => void\n}\n\n/**\n * One sandboxed widget iframe. A frame first opened in `preview` mode holds\n * css + bootstrap, receives streamed body html through a MessagePort, and is\n * finalized in place when `mode` turns `final` (html + code are posted, the\n * document is not rebuilt). A frame first opened in `final` mode (replay,\n * reload) gets the complete document at once.\n */\nexport function WidgetFrame(props: WidgetFrameProps) {\n  const ref = useRef<HTMLIFrameElement>(null)\n  const persist = props.persist !== false && !props.controlled\n  const theme = useRef(readTheme())\n  const [height, setHeight] = useState(() => heights.get(props.callId)\n    ?? (persist ? getUiState<number>(props.callId, 'height') : undefined)\n    ?? clampHeight(props.initialHeight ?? 160, props.policy.maxHeight))\n  const [action, setAction] = useState<{ id: number; request: ActionRequest } | undefined>(undefined)\n  const pendingAction = useRef(false)\n  const actionFlight = useRef(false)\n  const actionEpoch = useRef(0)\n  const [actionStatus, setActionStatus] = useState('')\n  /** The widget navigated its frame away; the card must say so. */\n  const [strayedNotice, setStrayedNotice] = useState(false)\n  const ready = useRef(false)\n  /** Whether the frame has received (or was built with) the final code. */\n  const finalized = useRef(false)\n  const errors = useRef<string[]>([])\n  /** The document-bound channel; never send host data to the WindowProxy. */\n  const port = useRef<MessagePort | null>(null)\n  const strayed = useRef(false)\n  const watched = useRef<HTMLIFrameElement | null>(null)\n  /** Whether the mount load of the current document has been seen. */\n  const ownLoad = useRef(false)\n  // Policies arrive as fresh objects (defaults while running, result meta once\n  // settled); key by value so an equal policy never rebuilds the document.\n  const resourceKey = JSON.stringify(props.resourceLibraries)\n  const policyKey = JSON.stringify(props.policy)\n  const policy = useMemo(() => props.policy, [policyKey]) // eslint-disable-line react-hooks/exhaustive-deps\n  // A reload must change srcdoc even when its visible content is identical.\n  // The fresh credential also rejects messages queued by the previous document.\n  const tok = useMemo(token, [props.css, policy, props.generation, resourceKey])\n  const guard = useMemo(() => new BridgeGuard({ policy }), [policy])\n  const live = useRef(props)\n  live.current = props\n\n  // Built once per frame lifetime: later html/code/theme changes travel by\n  // the MessagePort so widget state survives. Only a different css or policy, or\n  // an explicit reload (generation), rebuilds the document.\n  const srcDoc = useMemo(() => {\n    const p = live.current\n    return buildFrameDocument({\n      resourceLibraries: p.resourceLibraries,\n      token: tok,\n      mode: p.mode,\n      css: p.css,\n      html: p.mode === 'final' ? p.html : '',\n      jsFunctions: p.jsFunctions,\n      jsExpressions: p.jsExpressions,\n      theme: theme.current,\n      policy,\n      state: p.mode === 'final' && persist ? getUiState(p.callId, 'widget') : undefined,\n    })\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tok, props.css, policy, props.generation, resourceKey])\n\n  // React reuses the iframe when srcDoc changes. Reset during commit, before\n  // its new load task, and revoke the old port and pending action authority.\n  useLayoutEffect(() => {\n    strayed.current = false\n    ownLoad.current = false\n    ready.current = false\n    finalized.current = live.current.mode === 'final'\n    errors.current = []\n    pendingAction.current = false\n    actionFlight.current = false\n    actionEpoch.current++\n    setAction(undefined)\n    setActionStatus('')\n    setStrayedNotice(false)\n    return () => {\n      port.current?.close()\n      port.current = null\n      ready.current = false\n      actionEpoch.current++\n    }\n  }, [srcDoc])\n\n  const post = (msg: Record<string, unknown>, target = port.current) => {\n    if (strayed.current || !target || target !== port.current) return\n    target.postMessage({ ...msg, __diui: tok })\n  }\n\n  const finalize = () => {\n    const p = live.current\n    if (finalized.current || !ready.current || p.mode !== 'final') return\n    finalized.current = true\n    post({ type: 'final', html: p.html, code: codePayload({ jsFunctions: p.jsFunctions, jsExpressions: p.jsExpressions, state: persist ? getUiState(p.callId, 'widget') : undefined }) })\n  }\n\n  useEffect(() => onThemeChange(() => {\n    const next = readTheme()\n    // DSH mutates <html>/<body> attributes for many reasons; only real token changes are sent.\n    if (JSON.stringify(next) === JSON.stringify(theme.current)) return\n    theme.current = next\n    post({ type: 'theme', css: themeCss(next), scheme: schemeOf(next) })\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  }), [tok])\n\n  // A later load removes the foreign UI. This is only a visual containment\n  // signal: an attacker can delay load with an unfinished subresource. Host\n  // data travels exclusively on the original document's MessagePort, so a\n  // delayed load cannot make the replacement document receive it.\n  // The callback ref follows element replacement; the layout effect above\n  // handles srcdoc rebuilds on the same element.\n  const contain = () => {\n    if (strayed.current) return\n    strayed.current = true\n    port.current?.close()\n    port.current = null\n    actionEpoch.current++\n    ready.current = false\n    finalized.current = false\n    errors.current = []\n    setStrayedNotice(true)\n    setAction(undefined)\n    pendingAction.current = false\n    actionFlight.current = false\n    live.current.onErrors?.([])\n  }\n\n  const onFrameLoad = () => {\n    if (strayed.current) return\n    if (!ownLoad.current) { ownLoad.current = true; return }\n    contain()\n  }\n  const onFrameLoadRef = useRef(onFrameLoad)\n  onFrameLoadRef.current = onFrameLoad\n  const stableLoad = useCallback(() => onFrameLoadRef.current(), [])\n  const attachFrame = useCallback((frame: HTMLIFrameElement | null) => {\n    if (watched.current) watched.current.removeEventListener('load', stableLoad)\n    watched.current = frame\n    ref.current = frame\n    if (!frame) return\n    // A fresh element means a fresh document lifecycle.\n    strayed.current = false\n    ownLoad.current = false\n    frame.addEventListener('load', stableLoad)\n  }, [stableLoad])\n\n  // Stream preview html; switch to the final widget in place.\n  useEffect(() => {\n    if (props.mode === 'preview') {\n      if (ready.current && !finalized.current) post({ type: 'html', html: processPartialHtml(props.html) })\n    } else {\n      finalize()\n    }\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [props.html, props.mode])\n\n  useLayoutEffect(() => {\n    const onPortMessage = (ev: MessageEvent, source: MessagePort) => {\n      if (strayed.current || source !== port.current) return\n      const msg = readFrameMessage(ev.data, tok)\n      if (!msg) return\n      const p = live.current\n      switch (msg.type) {\n        case 'ready':\n          ready.current = true\n          if (!msg.final) {\n            if (p.mode === 'preview') post({ type: 'html', html: processPartialHtml(p.html) })\n            else finalize()\n          }\n          break\n        case 'resize': {\n          const h = clampHeight(msg.height, p.policy.maxHeight)\n          heights.set(p.callId, h)\n          if (persist && finalized.current) setUiState(p.callId, 'height', h)\n          setHeight(h)\n          break\n        }\n        case 'state':\n          if (persist && finalized.current) setUiState(p.callId, 'widget', msg.state)\n          break\n        case 'error':\n          if (finalized.current) {\n            errors.current = [...errors.current, `${msg.kind}: ${msg.message}`].slice(-20)\n            p.onErrors?.(errors.current)\n          }\n          break\n        case 'rpc':\n          void handleRpc(msg.id, msg.method, msg.params, source)\n          break\n      }\n    }\n    const handleRpc = async (id: number, method: string, params: Record<string, unknown>, source: MessagePort) => {\n      const reply = (msg: Record<string, unknown>) => post(msg, source)\n      const p = live.current\n      try {\n        if (!finalized.current || p.mode !== 'final') throw new BridgeError('unavailable', 'the widget is still generating')\n        if (method === 'sendPrompt') {\n          const text = guard.admitPrompt(params.text)\n          p.onSending?.(true)\n          try { await p.sendPrompt(text) } finally { p.onSending?.(false) }\n          p.onSent?.(true)\n          reply({ type: 'rpc-result', id, ok: true, value: { accepted: true } })\n        } else if (method === 'readData') {\n          if (!p.controlled) throw new Error('Data binding unavailable')\n          const entry = p.controlled.readData(contextOf(p), params.dataRef)\n          reply({ type: 'rpc-result', id, ok: true, value: entry.value })\n        } else if (method === 'invokeAction') {\n          if (!p.controlled) throw new Error('Actions unavailable')\n          if (pendingAction.current) throw new Error('An action is already awaiting confirmation')\n          const request = p.controlled.prepareAction(contextOf(p), params)\n          pendingAction.current = true\n          setAction({ id, request }); setActionStatus('')\n          // Generated code never receives authority to execute. A native host control below does.\n        } else if (method === 'openLink') {\n          const url = guard.admitLink(params.url)\n          window.open(url, '_blank', 'noopener,noreferrer')\n          reply({ type: 'rpc-result', id, ok: true, value: { opened: true } })\n        } else {\n          throw new BridgeError('unavailable', `unknown bridge method ${method}`)\n        }\n      } catch (err) {\n        const reason = err instanceof Error ? err.message : String(err)\n        if (method === 'sendPrompt') p.onSent?.(false, reason)\n        reply({ type: 'rpc-result', id, ok: false, error: reason })\n      }\n    }\n    // The bootstrap transfers a port before any generated code runs. Never\n    // transfer a host-created port back through a potentially navigated window.\n    const onConnect = (ev: MessageEvent) => {\n      const frame = ref.current\n      if (!frame || ev.source !== frame.contentWindow || strayed.current) return\n      if (ev.data?.type !== 'connect' || ev.data.__diui !== tok || ev.ports.length !== 1) return\n      const incoming = ev.ports[0]!\n      if (port.current) { incoming.close(); return }\n      port.current = incoming\n      incoming.onmessage = ev => onPortMessage(ev, incoming)\n      incoming.start()\n    }\n    window.addEventListener('message', onConnect)\n    return () => {\n      window.removeEventListener('message', onConnect)\n      port.current?.close()\n      port.current = null\n    }\n  // Layout registration precedes srcdoc's first script/connection task.\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tok, guard])\n\n  const finishAction = async (event: Event, accepted: boolean) => {\n    if (!action || !pendingAction.current || actionFlight.current) return\n    actionFlight.current = true\n    const epoch = actionEpoch.current\n    setActionStatus('Loading…')\n    try {\n      if (!accepted) throw new Error('Action cancelled')\n      const p = live.current\n      if (!p.controlled) throw new Error('Actions unavailable')\n      const value = await p.controlled.invokeAction(contextOf(p), action.request, event)\n      if (actionEpoch.current !== epoch) return\n      post({ type: 'rpc-result', id: action.id, ok: true, value })\n      setActionStatus('Success')\n    } catch (err) {\n      if (actionEpoch.current !== epoch) return\n      const reason = err instanceof Error ? err.message : String(err)\n      post({ type: 'rpc-result', id: action.id, ok: false, error: reason }); setActionStatus('Error: ' + reason)\n    } finally {\n      // A rebuilt document may already have staged its own request; leave it.\n      if (actionEpoch.current === epoch) { pendingAction.current = false; actionFlight.current = false; setAction(undefined) }\n    }\n  }\n  return (<>\n    {action && pendingAction.current && <div className=\"diui-card\" role=\"group\" aria-label=\"Requested action\">\n      <strong>{action.request.actionId}</strong><pre className=\"diui-code\">{JSON.stringify(action.request.args, null, 2)}</pre>\n      <button type=\"button\" className=\"diui-button\" onClick={e => { void finishAction(e.nativeEvent, true) }}>Run action</button>\n      <button type=\"button\" className=\"diui-button\" onClick={e => { void finishAction(e.nativeEvent, false) }}>Cancel</button>\n    </div>}\n    {actionStatus && <span role=\"status\">{actionStatus}</span>}\n    {strayedNotice\n      // Unmounting the element destroys the foreign document too, so nothing\n      // keeps running or receiving in place of the widget.\n      ? <div className=\"diui-card\" role=\"alert\" data-widget-strayed=\"true\">{props.strayedMessage ?? 'The widget navigated to another page and was removed'}</div>\n      : <iframe\n        ref={attachFrame}\n        className=\"diui-frame\"\n        title={props.title}\n        sandbox=\"allow-scripts allow-forms\"\n        referrerPolicy=\"no-referrer\"\n        srcDoc={srcDoc}\n        style={{ height }}\n        data-mode={props.mode}\n      />}\n  </>)\n}\n\nfunction clampHeight(h: number, max: number): number {\n  return Math.max(50, Math.min(max, Math.round(h)))\n}\n"
    },
    {
      "path": "client-src/widget/frame.ts",
      "content": "/**\n * Build the srcdoc for a widget frame. The frame is an opaque-origin sandbox\n * (`sandbox=\"allow-scripts allow-forms\"`, never `allow-same-origin`), so the\n * only channel to the host is a document-bound MessagePort, bootstrapped\n * through postMessage with a fresh per-document token.\n *\n * Layout of the document (after OpenIntelligentUI's frame-content.ts):\n * CSP meta → importmap → theme variables → base design CSS → widget css →\n * bootstrap (bridge, resize, morph, UI runtime) → body markup → code payload\n * (final only).\n *\n * A frame opened in `preview` mode is finalized in place: the host posts a\n * `final` message with the complete html and code, the bootstrap morphs the\n * markup and runs the code. The iframe is never rebuilt between streaming and\n * the finished widget, so there is no blank flash or height jump.\n */\nimport { offlinePack, resourceMode } from '../resources.ts'\nimport IDIOMORPH_SOURCE from 'idiomorph-source'\nimport type { WidgetPolicy } from '../policy.ts'\n\nexport interface FrameInput {\n  token: string\n  mode: 'preview' | 'final'\n  css: string\n  html: string\n  jsFunctions?: string\n  jsExpressions?: readonly string[]\n  theme: Readonly<Record<string, string>>\n  policy: WidgetPolicy\n  /** Persisted widget state (`UI.state` + auto-captured control values), final mode only. */\n  state?: unknown\n  /** Internal catalog frames embed only the library they use. */\n  resourceLibraries?: readonly string[]\n}\n\n/** Bare-specifier aliases for popular libraries, served from esm.sh when allowed. */\nconst IMPORTS: Record<string, string> = {\n  three: 'https://esm.sh/three@0.169.0',\n  'three/addons/': 'https://esm.sh/three@0.169.0/examples/jsm/',\n  d3: 'https://esm.sh/d3@7.9.0',\n  'chart.js/auto': 'https://esm.sh/chart.js@4.4.4/auto',\n  gsap: 'https://esm.sh/gsap@3.12.5',\n  'canvas-confetti': 'https://esm.sh/canvas-confetti@1.9.3',\n}\n\n/** Origins must be plain https origins to enter the CSP; anything else is dropped. */\nexport function safeOrigins(list: readonly string[]): string[] {\n  const out: string[] = []\n  for (const raw of list) {\n    try {\n      const u = new URL(raw)\n      if (u.protocol === 'https:' && u.origin !== 'null') out.push(u.origin)\n    } catch { /* not a URL */ }\n  }\n  return [...new Set(out)]\n}\n\n/**\n * CSP for one frame.\n *\n * `connect-src` is the only directive that follows `allowNetwork`: the resource\n * directives always carry the CDN allowlist, because widgets load libraries,\n * fonts and images from it. safeOrigins() emits origin-only sources, so this\n * policy does not restrict resource paths. CSP supports path sources, but\n * ignores queries (and path matching after redirects); even a path prefix\n * permits data in its suffix or query. An empty `cdn` blocks external resource\n * requests, but cannot stop self-navigation. The per-channel matrix,\n * including why each grant is needed, is in docs/widget-csp-audit.md.\n */\nexport function contentSecurityPolicy(policy: WidgetPolicy): string {\n  const cdn = offlinePack ? '' : safeOrigins(policy.cdn).join(' ')\n  const connect = policy.allowNetwork && cdn ? cdn : \"'none'\"\n  return [\n    \"default-src 'none'\",\n    `script-src 'unsafe-inline' 'unsafe-eval' blob: ${cdn}`.trim(),\n    `style-src 'unsafe-inline' ${cdn}`.trim(),\n    `img-src data: blob: ${cdn}`.trim(),\n    `font-src data: ${cdn}`.trim(),\n    `media-src data: blob: ${cdn}`.trim(),\n    `connect-src ${connect}`,\n    // canvas-confetti (an advertised import) runs its default path in a\n    // blob: Worker; a blob worker inherits this document's CSP and opaque\n    // origin, so it adds no reach (verified in scripts/security/audit.mjs).\n    'worker-src blob:',\n    \"form-action 'none'\",\n    \"base-uri 'none'\",\n  ].join('; ')\n}\n\n/** Escape text so it can sit inside an HTML <script>/<style> element without closing it. */\nexport function escapeForRawText(text: string, tag: 'script' | 'style